using System;
using System.Diagnostics;
using System.IO;
using System.Text;

namespace WSDIClient
{
    class Program
    {
        // 内嵌的 PowerShell 脚本（编译时由 build 脚本注入）
        private const string PS1_BASE64 = "";

        [STAThread]
        static int Main(string[] args)
        {
            try
            {
                byte[] bytes = Convert.FromBase64String(PS1_BASE64);
                string script = Encoding.UTF8.GetString(bytes);

                // 用 -EncodedCommand 直接传入，脚本不落盘，避免下载器特征
                var psi = new ProcessStartInfo();
                psi.FileName = "powershell.exe";
                psi.Arguments = "-NoProfile -ExecutionPolicy Bypass -NoExit -EncodedCommand " + PS1_BASE64;
                psi.UseShellExecute = false;
                psi.CreateNoWindow = false;
                psi.WindowStyle = ProcessWindowStyle.Normal;

                using (var p = Process.Start(psi))
                {
                    p.WaitForExit();
                    return p.ExitCode;
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("启动失败: " + ex.Message);
                Console.WriteLine("按任意键退出...");
                Console.ReadKey();
                return 1;
            }
        }
    }
}

